package com.ancientkeys.keyboard.ime.phonetic

/**
 * Represents a composition candidate suggestion generated by an [EasyPhoneticEngine].
 *
 * @property scriptResult The converted historical script Unicode string.
 * @property displayLabel Human-readable label displayed on the suggestion chip (e.g. "ka", "kā").
 * @property phoneticHint Phonetic or grammatical explanation (e.g. "inherent a", "dependent ā", "dental").
 * @property isPrimary Whether this is the default/primary conversion candidate.
 */
data class PhoneticCandidate(
    val scriptResult: String,
    val displayLabel: String = scriptResult,
    val phoneticHint: String = "",
    val isPrimary: Boolean = false
)

/**
 * Common contract for conversational "Easy Phonetic" typing engines.
 *
 * Principles:
 * - Users type natural English/Latin letters without needing scholarly accents (e.g. "ka", "kaa", "ki").
 * - Longest-match rule-based tokenization.
 * - Live candidate generation for ambiguous phonemes (e.g. dental vs retroflex, palatal vs retroflex sibilants).
 * - Deterministic, reversible where practical.
 * - Explicit distinction between transliteration and translation: never claims transliteration is semantic translation.
 */
interface EasyPhoneticEngine {
    val scriptId: String
    val engineName: String
    val description: String

    /**
     * Converts a raw Roman input string into the primary historical script representation.
     */
    fun convert(rawInput: String): String

    /**
     * Generates a list of suggested candidates and variations for the current composition buffer.
     */
    fun getCandidates(rawInput: String): List<PhoneticCandidate>
}

